async function hydratePublicContent(){if(publicContentHydrationStarted)return;publicContentHydrationStarted=true;try{const [posts,projects,spaces,events]=await Promise.all([listPosts({pageSize:100}),listProjects({pageSize:100}),listSpaces({pageSize:100}),listEvents({pageSize:100})]);if(posts.source==='supabase'&&posts.count>0){FEED_POSTS.splice(0,FEED_POSTS.length,...posts.data.map((post,index)=>({author:post.author_name||'Membru Viziunea',initial:(post.author_name||'M')[0],role:'Membru',time:new Date(post.created_at).toLocaleDateString('ro-RO'),city:post.city||'Online',distance:0,interest:post.interest||'Comunitate',title:post.title,body:post.body,action:'Vezi postarea'})));}const replaceResults=(key,result,metaFallback)=>{if(result.source==='supabase'&&result.count>0)DEMO_RESULTS[key]=result.data.map(item=>({title:item.title,meta:item.city||metaFallback,desc:item.description||item.body||''}));};replaceResults('proiecte',projects,'Proiect în comunitate');replaceResults('spatii',spaces,'Spațiu în comunitate');replaceResults('evenimente',events,'Eveniment în comunitate');if(path()==='/feed'||path()==='/exploreaza')render();}catch(error){publicContentHydrationStarted=false;if(error?.code!=='PGRST205')console.warn('Public content sync unavailable; keeping demo fallback',error);}}
