function enhanceFeedCityFilter(){if(path()!=='/feed'||feedMode==='create')return;const locationCard=app.querySelector('.feed-location>div');if(!locationCard)return;let select=locationCard.querySelector('[data-feed-city]');const cities=[...new Set(FEED_POSTS.map(post=>post.city).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ro'));if(!select){const current=demoFeed.city;locationCard.querySelector('strong')?.remove();locationCard.querySelector('small')?.remove();locationCard.insertAdjacentHTML('afterbegin',`<label>Oraș<select data-feed-city><option value="">Toate orașele</option>${cities.map(city=>`<option value="${city}" ${city===current?'selected':''}>${city}</option>`).join('')}</select></label><small>Sunt afișate doar orașele cu rezultate · orașul profilului este selectat automat</small>`);select=locationCard.querySelector('[data-feed-city]');}if(select)select.value=demoFeed.city||'';const allVisiblePosts=FEED_POSTS.filter(post=>(!demoFeed.interests.length||demoFeed.interests.includes(post.interest))&&(post.distance===0||post.distance<=Number(demoFeed.radius)));const visiblePosts=allVisiblePosts.filter(post=>!demoFeed.city||post.city===demoFeed.city);app.querySelectorAll('.feed-post').forEach((post,index)=>{post.hidden=!allVisiblePosts[index]||Boolean(demoFeed.city&&allVisiblePosts[index].city!==demoFeed.city);});const heading=app.querySelector('.community-feed h2');if(heading)heading.textContent=`${visiblePosts.length} ${visiblePosts.length===1?'postare relevantă':'postări relevante'}`;}
