function enhanceAdminOnboarding(){if(path()!=='/admin')return;const heading=app.querySelector('.admin-heading');if(!heading||app.querySelector('.admin-onboarding'))return;const pending=ADMIN_MEMBERS.filter(member=>member.status==='În așteptare');const section=document.createElement('section');section.className='admin-onboarding';section.innerHTML=`<div class="admin-section-heading"><div><span class="page-kicker">Prioritate · acces în comunitate</span><h2>Intrări noi de validat</h2><p>Aceste persoane au cerut acces și trebuie verificate înainte să devină membre active.</p></div><strong>${pending.length} ${pending.length===1?'intrare nouă':'intrări noi'}</strong></div>${pending.length?`<div class="onboarding-list">${pending.map(member=>`<article class="onboarding-card"><div class="onboarding-identity"><span class="member-avatar">${esc(member.name[0])}</span><div><h3>${esc(member.name)} <span>Nou</span></h3><p>${esc(member.email)}</p></div></div><dl><div><dt>Înregistrat</dt><dd>${esc(member.registered||'—')}</dd></div><div><dt>Telefon</dt><dd>${esc(member.phone||'Nu a fost adăugat')}</dd></div><div><dt>Oraș</dt><dd>${esc(member.city||'—')}</dd></div><div><dt>Roluri</dt><dd>${esc((member.roles||[]).join(' · ')||'—')}</dd></div><div><dt>Interese</dt><dd>${esc(member.interests||'—')}</dd></div><div><dt>Activitate</dt><dd>${esc(member.active||'Încă nu')}</dd></div></dl><button type="button" class="onboarding-review" data-onboarding-review="${esc(member.email)}">Începe verificarea</button></article>`).join('')}</div>`:'<div class="onboarding-empty">Nu există intrări noi care așteaptă validarea.</div>'}`;heading.after(section);}
function enhanceAdminPosts(){if(path()!=='/admin')return;const table=app.querySelector('.members-table');if(!table||app.querySelector('.admin-feed-moderation'))return;const section=document.createElement('section');section.className='admin-feed-moderation';section.innerHTML=`<div class="admin-section-heading"><div><span class="page-kicker">Admin · Feed moderation</span><h2>Propuneri pentru Feed</h2><p>Verifică postările trimise de membri înainte să devină vizibile în comunitate.</p></div><strong>${adminPosts.filter(post=>post.status==='pending').length} în așteptare</strong></div><div class="moderation-list">${adminPosts.length?adminPosts.map(post=>`<article class="moderation-card" data-moderation-post="${esc(post.id)}"><div class="moderation-card-top"><span class="moderation-status ${post.status==='pending'?'is-pending':post.status==='published'?'is-approved':'is-rejected'}">${post.status==='pending'?'În moderare':post.status==='published'?'Aprobată':'Dezaprobată'}</span><time>${post.created_at?new Date(post.created_at).toLocaleDateString('ro-RO'):''}</time></div><h3>${esc(post.title||'Fără titlu')}</h3><p>${esc(post.body||post.description||'')}</p><div class="moderation-meta"><span>${esc(post.author_name||'Membru')}</span><span>${esc(post.entity_type||'Postare')} · ${esc(post.city||'Online')}</span><span>${esc((post.interests||[post.interest]).filter(Boolean).join(' · '))}</span></div>${post.status==='pending'?`<div class="moderation-actions"><button type="button" data-moderation-action="published" data-post-id="${esc(post.id)}">Aprobă</button><button type="button" data-moderation-action="rejected" data-post-id="${esc(post.id)}">Dezaprobă</button></div>`:''}</article>`).join(''):'<div class="feed-empty"><strong>Nu există propuneri de Feed.</strong><span>Postările noi trimise spre moderare vor apărea aici.</span></div>'}</div>`;table.after(section);}
