const messageDistance=(city,origin=demoProfile.city)=>{if(!city||city==='Online')return 0;if(city===origin)return 0;const distances={'București':{'Cluj-Napoca':325,'Iași':390,'Brașov':185,'Sibiu':280},'Cluj-Napoca':{'București':325,'Iași':390,'Brașov':275,'Sibiu':180}};return distances[origin]?.[city]||distances.București?.[city]||999;};
