function renderMessages(){if(path()!=='/mesaje')return;app.innerHTML=messagesView();bind();}
function messagesView(){const members=messageMembers();const cities=[...new Set(members.map(member=>member.city))].sort((a,b)=>a.localeCompare(b,'ro'));const roles=[...new Set(members.flatMap(member=>member.roles))].sort();const interests=[...new Set(members.flatMap(member=>member.interests.split(', ')))].sort();const conversations=[...new Map(messagingData.map(message=>{const member=memberForMessage(message);return [member.email,member];})).values()];const selected=members.find(member=>member.email===messageTargetEmail)||conversations.find(member=>member.email===messageTargetEmail);const chat=selected?messageConversationMessages(selected.email):[];return `${navbar()}<main class="page messages-page"><div class="messages-heading"><div><span class="page-kicker">Comunicare</span><h1>Mesaje</h1><p class="page-intro">Găsește oameni din comunitate și continuă conversațiile într-un singur loc.</p></div><strong class="community-count">${members.length+1} membri în comunitate</strong></div><section class="message-directory"><div class="directory-heading"><div><span class="page-kicker">Găsește oameni</span><h2>Toți membrii comunității</h2><p><strong data-message-result-count>${members.length}</strong> rezultate</p></div><input data-message-search type="search" placeholder="Caută după nume..." aria-label="Caută după nume"></div><div class="message-filters"><label>Oraș<select data-message-filter="city"><option value="">Toate orașele</option>${cities.map(city=>`<option value="${esc(city)}">${esc(city)}</option>`).join('')}</select></label><label>Distanță<select data-message-filter="distance"><option value="">Orice distanță</option><option value="25">până la 25 km</option><option value="100">până la 100 km</option><option value="250">până la 250 km</option><option value="500">până la 500 km</option></select></label><label>Rol<select data-message-filter="role"><option value="">Orice rol</option>${roles.map(role=>`<option value="${esc(role)}">${esc(role)}</option>`).join('')}</select></label><label>Interese<select data-message-filter="interest"><option value="">Orice interes</option>${interests.map(interest=>`<option value="${esc(interest)}">${esc(interest)}</option>`).join('')}</select></label></div><div class="message-member-results" data-message-members>${members.map(member=>`<button type="button" class="message-member-card" data-message-member="${esc(member.email)}" data-name="${esc(member.name.toLowerCase())}" data-city="${esc(member.city)}" data-distance="${messageDistance(member.city)}" data-roles="${esc(member.roles.join('|'))}" data-interests="${esc(member.interests)}"><span class="member-avatar">${esc(member.name[0])}</span><span><strong>${esc(member.name)}</strong><small>${esc(member.roles.join(' · '))} · ${esc(member.city)}</small></span><span class="member-card-action">Mesaj →</span></button>`).join('')}</div><p class="message-no-results" data-message-empty hidden>Nu am găsit membri pentru filtrele alese.</p></section><section class="messenger-layout"><aside class="conversation-sidebar"><header><h2>Conversațiile tale</h2><span>${conversations.length}</span></header><div class="conversation-list">${conversations.length?conversations.map(member=>`<button type="button" class="conversation-item ${selected?.email===member.email?'selected':''}" data-message-member="${esc(member.email)}"><span class="member-avatar">${esc(member.name[0])}</span><span><strong>${esc(member.name)}</strong><small>${esc(messageConversationMessages(member.email).at(-1)?.body||'Deschide conversația')}</small></span></button>`).join(''):'<div class="conversation-empty">Nu ai încă conversații.<br><small>Alege un membru de mai sus pentru a începe.</small></div>'}</div></aside><section class="chat-panel">${selected?`<header class="chat-header"><span class="member-avatar">${esc(selected.name[0])}</span><div><h2>${esc(selected.name)}</h2><small>${esc(selected.roles.join(' · '))} · ${esc(selected.city)}</small></div></header><div class="chat-messages">${chat.length?chat.map(message=>{const mine=(message.from||message.sender_id)===currentUser?.email||(message.from||message.sender_id)===currentUser?.id;return `<div class="chat-bubble ${mine?'mine':''}"><p>${esc(message.body)}</p><time>${new Date(message.created_at).toLocaleString('ro-RO')}</time></div>`;}).join(''):'<div class="chat-empty"><strong>Începe conversația cu ${esc(selected.name)}</strong><span>Trimite un mesaj și va apărea aici.</span></div>'}</div><form class="chat-composer" id="messenger-chat-form"><textarea name="body" rows="1" required placeholder="Scrie un mesaj..."></textarea><button type="submit" aria-label="Trimite mesajul">→</button></form>`:'<div class="chat-empty chat-empty-large"><span class="chat-empty-icon">✦</span><strong>Selectează o conversație</strong><span>Alege un membru sau o conversație din stânga pentru a începe să vorbești.</span></div>'}</section></section></main>${footer()}`;}
function notificationsView(){return `${navbar()}<main class="page notifications-page"><span class="page-kicker">Activitatea contului</span><h1>Notificări</h1><p class="page-intro">Aici vezi mesajele și activitatea care te privește.</p><section class="notification-list">${notificationData.length?notificationData.map(notification=>`<article class="notification-item"><span class="notification-dot"></span><div><strong>${esc(notification.title)}</strong><p>${esc(notification.body||'')}</p><small>${new Date(notification.created_at).toLocaleString('ro-RO')}</small></div></article>`).join(''):'<div class="feed-empty"><strong>Nu ai notificări noi.</strong></div>'}</section></main>${footer()}`;}
async function hydrateMessaging(){const key=`${currentUser?.id||''}:${path()}`;if(!currentUser||messagingHydratedKey===key)return;messagingHydratedKey=key;try{if(path()==='/mesaje'){messagingData=(await listMessages(currentUser)).data;app.innerHTML=messagesView();}else if(path()==='/notificari'){notificationData=(await listNotifications(currentUser)).data;app.innerHTML=notificationsView();}bind();}catch(error){messagingHydratedKey='';console.warn('Messaging sync unavailable',error);}}
const shell=(title,cls='')=>{const directionKey=path().split('/').pop();const [intro,items]=PAGE_CONTENT[path()]|| (DIRECTION_CONTENT[directionKey]&&['Structura direcției',DIRECTION_CONTENT[directionKey]]) || ['Structură de pagină',['Conținutul acestei pagini va fi construit ulterior']];return `${navbar()}<main class="page ${cls}"><span class="page-kicker">Page shell</span><h1>${esc(title)}</h1><p class="page-intro">${esc(intro)}</p><ul class="page-outline">${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></main>${footer()}`;};
const exploreLocationOptions=(results,locations)=>{const counts=results.reduce((total,_,index)=>{const city=locations[index%locations.length];total[city]=(total[city]||0)+1;return total;},{});return `<option value="">Toate locațiile (${results.length})</option>${Object.entries(counts).map(([city,count])=>`<option value="${city}">${city} (${count})</option>`).join('')}`;};
function exploreView(){const active=exploreCategories.some(([id])=>id===location.hash.slice(1))?location.hash.slice(1):'oameni';const results=DEMO_RESULTS[active];const directions=['Artă','Educație','Turism','Servicii Creative','Intervenție Culturală'];const locations=['București','Cluj-Napoca','Iași','Brașov'];const periods=['Acum','Viitoare','Arhivă'];return `${navbar()}<main class="page explore-page"><span class="page-kicker">Page shell</span><h1>Explorează</h1><p class="page-intro">Ce există în ecosistem</p><div class="explore-pills" role="tablist">${exploreCategories.map(([id,label])=>`<a class="explore-pill ${id===active?'selected':''}" href="/exploreaza#${id}" role="tab" aria-selected="${id===active}">${label}</a>`).join('')}</div><section class="explore-filter-bar"><label>Direcție<select class="explore-filter" data-filter="direction"><option value="">Toate direcțiile</option>${directions.map(value=>`<option>${value}</option>`).join('')}</select></label><label>Locație<select class="explore-filter" data-filter="location">${exploreLocationOptions(results,locations)}</select></label><label>Perioadă<select class="explore-filter" data-filter="period"><option value="">Toate perioadele</option>${periods.map(value=>`<option>${value}</option>`).join('')}</select></label><button class="filter-reset" data-explore-reset type="button">Resetează</button><span class="filter-count" data-explore-count>${results.length} rezultate</span></section><section class="demo-results"><span class="page-kicker">Demo results · date fictive</span><h2>${esc(exploreCategories.find(([id])=>id===active)[1])}</h2><div class="result-grid">${results.map((item,index)=>`<article class="result-card" data-result data-direction="${directions[index%directions.length]}" data-location="${locations[index%locations.length]}" data-period="${periods[index%periods.length]}"><span>0${index+1}</span><strong>${esc(item.title)}</strong><b>${esc(item.meta)}</b><small>${esc(item.desc)}</small><button class="person-more" data-explore-detail="${active}" data-detail-index="${index}" type="button">Vezi mai multe <span>→</span></button></article>`).join('')}</div><p class="empty-explore" hidden>Nu există rezultate pentru combinația aleasă.</p></section></main>${footer()}`;}
function profileView(){const roles=['Creator','Trainer','Participant','Voluntar','Partner','Gazdă de spațiu'];const interests=['Artă','Educație','Experiențe','Turism','Evenimente','Proiecte','Spații'];const cities=['București','Cluj-Napoca','Iași','Brașov','Sibiu'];return `${navbar()}<main class="page profile-page"><span class="page-kicker">Page shell · Demo profile</span><section class="profile-hero"><div class="large-avatar">Z</div><div><h1>Zametheea</h1><p>zametheea@demo.viziunea.ro</p></div></section><section class="profile-selectors"><article><span class="page-kicker">Roluri</span><h2>Ce roluri te reprezintă?</h2><p>Selectează sau deselectează oricând rolurile care te reprezintă.</p><div class="profile-choices">${roles.map(role=>`<button class="profile-choice ${demoProfile.roles.includes(role)?'selected':''}" data-profile-type="roles" data-profile-value="${role}" type="button">${role}</button>`).join('')}</div></article><article><span class="page-kicker">Interese</span><h2>Ce te interesează?</h2><p>Alege domeniile pe care vrei să le urmărești în profilul tău.</p><div class="profile-choices">${interests.map(interest=>`<button class="profile-choice ${demoProfile.interests.includes(interest)?'selected':''}" data-profile-type="interests" data-profile-value="${interest}" type="button">${interest}</button>`).join('')}</div></article><article class="profile-location"><span class="page-kicker">Locație</span><h2>Care este orașul tău?</h2><p>Îl folosim ca punct de plecare pentru recomandările locale.</p><label>Oraș<select data-profile-city>${cities.map(city=>`<option ${city===demoProfile.city?'selected':''}>${city}</option>`).join('')}</select></label></article></section><section class="profile-structure"><article><span class="page-kicker">Identitate</span><h2>Profilul meu</h2><ul><li>Nume și date de contact</li><li>Despre mine</li></ul></article><article><span class="page-kicker">Prezență</span><h2>Despre mine</h2><ul><li>Scurtă prezentare</li><li>Oraș și disponibilitate</li><li>Linkuri publice</li></ul></article></section></main>${footer()}`;}
function feedView(){const choices=['Artă','Educație','Experiențe','Turism','Evenimente','Proiecte','Spații'];const radii=[10,25,50,100,250];const posts=FEED_POSTS.filter(post=>(!demoFeed.interests.length||demoFeed.interests.includes(post.interest))&&(post.distance===0||post.distance<=Number(demoFeed.radius)));return `${navbar()}<main class="page feed-page"><span class="page-kicker">Zona personală</span><h1>Feed</h1><p class="page-intro">Postări din comunitate, potrivite intereselor și zonei tale.</p><div class="feed-preferences">${choices.map(choice=>`<button class="feed-choice ${demoFeed.interests.includes(choice)?'selected':''}" data-feed-interest="${choice}" type="button">${choice}</button>`).join('')}</div><section class="feed-location"><div><span class="page-kicker">Recomandări locale</span><strong>${esc(demoFeed.city)}</strong><small>Oraș preluat automat din profil</small></div><label>Raza față de oraș<select data-feed-radius>${radii.map(radius=>`<option value="${radius}" ${Number(demoFeed.radius)===radius?'selected':''}>${radius} km</option>`).join('')}</select></label></section><section class="community-feed"><header><div><span class="page-kicker">Comunitatea ta</span><h2>${posts.length} ${posts.length===1?'postare relevantă':'postări relevante'}</h2></div><small>Date demonstrative</small></header><div class="feed-posts">${posts.length?posts.map(post=>`<article class="feed-post"><div class="feed-post-author"><span class="feed-post-avatar">${post.initial}</span><div><strong>${esc(post.author)}</strong><small>${esc(post.role)} · ${esc(post.time)}</small></div><span class="feed-post-distance">${post.distance?`${post.distance} km · `:''}${esc(post.city)}</span></div><div class="feed-post-content"><span class="feed-post-tag">${esc(post.interest)}</span><h3>${esc(post.title)}</h3><p>${esc(post.body)}</p></div><footer><button type="button">${esc(post.action)}</button><div><button type="button" aria-label="Salvează">♡</button><button type="button" aria-label="Distribuie">↗</button></div></footer></article>`).join(''):`<div class="feed-empty"><strong>Nu sunt încă postări pentru combinația aleasă.</strong><span>Extinde raza sau selectează încă un interes.</span></div>`}</div></section></main>${footer()}`;}
function authView(){return `<main class="auth-page"><section class="auth-card"><a class="site-logo" href="/admin">Viziunea<span>✳</span></a><span class="page-kicker">Comunitatea Viziunea · Demo</span><h1>Intră în cont</h1><p>Continuă cu profilul demo Zametheea pentru a vedea zona personală.</p><form id="auth-form"><label>Nume<input name="display_name" autocomplete="name" value="Zametheea"></label><label>Email<input name="email" type="email" autocomplete="email" required value="zametheea@demo.viziunea.ro"></label><button class="account-cta" type="submit">Continuă <span>→</span></button></form><p class="auth-message">${esc(authNotice)}</p></section></main>`;}
function optionCounts(values, field){return values.map(value=>{const count=ADMIN_MEMBERS.filter(member=>field==='interest'?member.interests.split(', ').includes(value):field==='role'?member.roles.includes(value):member[field]===value).length;return `<option value="${value}">${value} (${count})</option>`;}).join('');}
function compactDate(value){const months={ianuarie:'01',februarie:'02',martie:'03',aprilie:'04',mai:'05',iunie:'06',iulie:'07',august:'08',septembrie:'09',octombrie:'10',noiembrie:'11',decembrie:'12'};const match=String(value).match(/^(\d{1,2})\s+([^\s]+)\s+(\d{4})$/i);return match?`${match[1].padStart(2,'0')}.${months[match[2].toLowerCase()]||match[2]}.${match[3].slice(-2)}`:value;}
function adminView(){const roles=[...new Set(ADMIN_MEMBERS.flatMap(member=>member.roles))].sort();const cities=[...new Set(ADMIN_MEMBERS.map(member=>member.city))].sort();const interests=[...new Set(ADMIN_MEMBERS.flatMap(member=>member.interests.split(', ')))].sort();const visibleMembers=adminHasServerPage?ADMIN_MEMBERS:ADMIN_MEMBERS.slice((adminPage-1)*25,adminPage*25);const total=adminHasServerPage?adminTotal:ADMIN_MEMBERS.length;return `<header class="site-header admin-header"><a class="site-logo" href="/admin">Viziunea<span>✳</span></a><span class="admin-badge">ADMIN · DEMO DATABASE</span><a href="/" class="nav-link">Înapoi la site</a></header><main class="admin-shell"><div class="admin-heading"><div><span class="page-kicker">Admin · Members database</span><h1>Membrii Viziunea</h1><p>Identitate, roluri și activitate în comunitate.</p></div><button class="admin-action" type="button">+ Adaugă membru</button></div><div class="admin-stats"><div><span>Total membri</span><strong>${total}</strong></div><div><span>Activi</span><strong>${ADMIN_MEMBERS.filter(member=>member.status==='Activ').length}</strong></div><div><span>Roluri selectate</span><strong>${new Set(ADMIN_MEMBERS.flatMap(member=>member.roles)).size}</strong></div><div><span>Orașe</span><strong>${new Set(ADMIN_MEMBERS.map(member=>member.city)).size}</strong></div></div><section class="member-filters"><div class="filter-search"><span>⌕</span><input id="member-search" type="search" placeholder="Caută după nume sau email"></div><label>Rol<select id="member-role"><option value="">Toate rolurile (${total})</option>${optionCounts(roles,'role')}</select></label><label>Oraș<select id="member-city"><option value="">Toate orașele (${total})</option>${optionCounts(cities,'city')}</select></label><label>Status<select id="member-status"><option value="">Orice status (${total})</option>${optionCounts(['Activ','În așteptare'],'status')}</select></label><label>Interes<select id="member-interest"><option value="">Orice interes (${total})</option>${optionCounts(interests,'interest')}</select></label><button class="filter-reset" id="filter-reset" type="button">Resetează</button><span class="filter-count" id="filter-count">${visibleMembers.length} ${visibleMembers.length===1?'membru':'membri'}</span></section><section class="members-table"><div class="members-table-head"><h2>Toți membrii</h2><span>${adminHasServerPage?'Date Supabase · pagină '+adminPage:'Date demo · sincronizare bază de date ulterior'}</span></div><div class="members-table-scroll"><table><thead><tr><th>Membru</th><th>Roluri</th><th>Locație</th><th>Înregistrat</th><th>Ultima activitate</th><th>Status</th></tr></thead><tbody>${visibleMembers.map(member=>`<tr data-member-row data-name="${member.name.toLowerCase()}" data-email="${member.email.toLowerCase()}" data-roles="${member.roles.join('|')}" data-city="${member.city}" data-status="${member.status}" data-interests="${member.interests}"><td><div class="member-person"><span class="member-avatar">${member.name[0]}</span><div><strong>${member.name}</strong><small>${member.email}</small></div></div></td><td><div class="member-roles">${member.roles.map(role=>`<span>${role}</span>`).join('')}</div><small class="member-interests">${member.interests}</small></td><td>${member.city}</td><td><time title="${member.registered}">${compactDate(member.registered)}</time></td><td>${member.active}</td><td><span class="member-status ${member.status==='Activ'?'is-active':'is-pending'}">${member.status}</span></td></tr>`).join('')}</tbody></table></div>${total>25?`<nav class="admin-pagination"><button type="button" data-admin-page="${adminPage-1}" ${adminPage===1?'disabled':''}>← Anterior</button><span>Pagina ${adminPage} din ${Math.ceil(total/25)}</span><button type="button" data-admin-page="${adminPage+1}" ${adminPage>=Math.ceil(total/25)?'disabled':''}>Următoarea →</button></nav>`:''}</section></main>`;}
function legacyRender(){document.body.classList.toggle('admin-mode',path()==='/admin');if(path()==='/admin')app.innerHTML=adminView();else if(path()==='/auth')app.innerHTML=authView();else if(path()==='/exploreaza')app.innerHTML=exploreView();else if(path()==='/profil')app.innerHTML=profileView();else if(path()==='/feed')app.innerHTML=feedView();else {const title=ROUTES[path()]||DIRECTIONS.find(([u])=>u===path())?.[1]||'Pagină';app.innerHTML=shell(title,path().slice(1).replaceAll('/','-')||'home');}bind();if(path()==='/admin'){enhanceAdminContacts();const header=app.querySelector('.members-table thead tr');if(header&&header.children[6]?.textContent==='Interese')header.insertBefore(header.children[6],header.children[2]);app.querySelectorAll('.members-table tbody tr').forEach(row=>{const cityCell=row.children[3];if(cityCell&&!cityCell.dataset.fullCity){const full=cityCell.textContent.trim();cityCell.dataset.fullCity=full;cityCell.innerHTML=`<span class="city-short" title="${full}">${full.slice(0,6)}…</span>`;}});app.querySelectorAll('.contact-actions a[title="WhatsApp"]').forEach((whatsapp,index)=>{whatsapp.title=`WhatsApp: ${ADMIN_MEMBERS[index].phone}`;});app.querySelectorAll('.member-avatar').forEach((avatar,index)=>{if(ADMIN_MEMBERS[index].note)avatar.insertAdjacentHTML('beforeend',`<span class="member-note" title="${ADMIN_MEMBERS[index].note.replace(/"/g,'&quot;')}">✎</span>`);});compactAdminPills();syncAdminFilterControls();void hydrateAdminMembers();}if(path()==='/exploreaza')enhanceExploreFilters();}
function enhanceExploreFilters(){const bar=app.querySelector('.explore-filter-bar');if(!bar||bar.querySelector('.explore-name-filter'))return;bar.insertAdjacentHTML('beforeend','<label class="explore-name-filter">Opțional · caută după nume<input class="explore-search" type="search" placeholder="Nume sau titlu"></label>');}
function updateExploreLocationCounts(query=''){const select=app.querySelector('[data-filter="location"]');if(!select)return;const cards=[...app.querySelectorAll('[data-result]')].filter(card=>!query||card.textContent.toLowerCase().includes(query));[...select.options].forEach((option,index)=>{const label=option.textContent.replace(/ \(\d+\)$/,'');const count=index===0?cards.length:cards.filter(card=>card.dataset.location===option.value).length;option.textContent=`${label} (${count})`;if(index>0){option.hidden=count===0;option.disabled=count===0;}});}
async function refreshExploreFromServer(){const active=exploreCategories.find(([id])=>id===location.hash.slice(1))?.[0]||'oameni';const kind={proiecte:'projects',spatii:'spaces',evenimente:'events'}[active];if(!kind)return false;const search=app.querySelector('.explore-search')?.value.trim()||'';const city=app.querySelector('[data-filter="location"]')?.value||'';const requestId=++exploreRequestId;try{const result=await listContent(kind,{page:1,pageSize:100,search,city});if(requestId!==exploreRequestId||result.source!=='supabase'||result.count===0)return false;DEMO_RESULTS[active]=result.data.map(item=>({title:item.title,meta:item.city||'În comunitate',desc:item.description||item.body||''}));render();const nextSearch=app.querySelector('.explore-search');const nextCity=app.querySelector('[data-filter="location"]');if(nextSearch)nextSearch.value=search;if(nextCity)nextCity.value=city;return true;}catch(error){if(error?.code!=='PGRST205')console.warn('Explore filter sync unavailable; using local fallback',error);return false;}}
function hasActiveCommunityAccount(){return Boolean(currentUser&&(String(currentUser.id||'').startsWith('demo:')||currentUser.status==='active'||currentUser.user_metadata?.status==='active'));}
function openMessageComposer(item){const dialog=document.createElement('dialog');dialog.className='message-composer';dialog.innerHTML=`<form method="dialog"><button class="detail-close" value="cancel" aria-label="Închide">×</button><span class="page-kicker">Mesaj pentru ${esc(item.title)}</span><h2>Începe o conversație</h2><textarea name="body" rows="6" required placeholder="Scrie un mesaj pentru ${esc(item.title)}..."></textarea><p class="message-composer-notice"></p><button class="admin-action" value="send">Trimite mesajul <span>→</span></button></form>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();const body=new FormData(event.target).get('body');try{await sendMessage({from:currentUser,to:{id:`demo:${item.email}`,email:item.email,user_metadata:{full_name:item.title}},body});dialog.querySelector('.message-composer-notice').textContent='Mesaj trimis. Radu va avea o notificare când intră în cont.';event.target.querySelector('textarea').value='';}catch(error){dialog.querySelector('.message-composer-notice').textContent=error.message||'Mesajul nu a putut fi trimis.';}});dialog.querySelector('.detail-close')?.addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>dialog.remove());}
function openExploreDetail(category,index){const item=DEMO_RESULTS[category]?.[index];if(!item)return;const dialog=document.createElement('dialog');dialog.className='explore-detail-dialog';if(!currentUser){dialog.innerHTML=`<button class="detail-close" type="button" aria-label="Închide">×</button><span class="page-kicker">Acces pentru membri</span><h2>Creează-ți un cont pentru a vedea mai multe</h2><p>Profilurile complete, datele de contact, resursele și detaliile comunității sunt disponibile membrilor Viziunea.</p><div class="access-steps"><span><b>1</b> Îți creezi profilul</span><span><b>2</b> Un moderator Viziunea îl validează</span><span><b>3</b> Primești acces la comunitate și beneficii</span></div><button class="admin-action detail-register" type="button">Creează contul</button>`;}else if(!hasActiveCommunityAccount()){dialog.innerHTML=`<button class="detail-close" type="button" aria-label="Închide">×</button><span class="page-kicker">Cont în curs de validare</span><h2>Un moderator verifică profilul tău</h2><p>După validare vei putea accesa profiluri complete, contacte, resurse și celelalte beneficii ale comunității.</p><button class="admin-action detail-close-secondary" type="button">Am înțeles</button>`;}else{const type=exploreCategories.find(([id])=>id===category)?.[1]||'Detaliu';dialog.innerHTML=`<button class="detail-close" type="button" aria-label="Închide">×</button><span class="page-kicker">${esc(type)} · profil complet</span><div class="detail-identity"><span>${esc(item.title[0])}</span><div><h2>${esc(item.title)}</h2><b>${esc(item.meta)}</b></div></div><p>${esc(item.desc)}</p><dl><div><dt>Disponibilitate</dt><dd>Deschis pentru conexiuni și colaborări în comunitate</dd></div><div><dt>Interese comune</dt><dd>Artă, educație și proiecte locale</dd></div><div><dt>Activitate</dt><dd>Membru activ · răspunde de obicei în 1–2 zile</dd></div></dl><button class="admin-action" data-message-to="${esc(item.email||'')}" type="button">Trimite un mesaj</button>`;}document.body.append(dialog);dialog.showModal();dialog.querySelectorAll('.detail-close,.detail-close-secondary').forEach(button=>button.addEventListener('click',()=>dialog.close()));dialog.querySelector('[data-message-to]')?.addEventListener('click',()=>{dialog.close();openMessageComposer(item);});dialog.querySelector('.detail-register')?.addEventListener('click',()=>{dialog.close();go('/auth?intent=register');});dialog.addEventListener('close',()=>dialog.remove());}
function openMemberEditor(member,row){const dialog=document.createElement('dialog');dialog.className='member-editor';dialog.innerHTML=`<form method="dialog"><button class="editor-close" value="cancel" aria-label="Închide">×</button><span class="page-kicker">Editează membru</span><h2>${member.name}</h2><label>Status<select name="status"><option ${member.status==='Activ'?'selected':''}>Activ</option><option ${member.status==='În așteptare'?'selected':''}>În așteptare</option><option>Dezaprobat</option></select></label><label>Notă internă<textarea name="note" rows="4" placeholder="Adaugă o notă despre acest membru...">${member.note||member.admin_note||''}</textarea></label><button class="admin-action" value="save">Salvează modificările</button></form>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.target);const nextStatus=data.get('status');const nextNote=String(data.get('note')||'').trim();try{if(member.id&&!String(member.id).startsWith('m-'))await updateMember(member.id,{status:nextStatus,note:nextNote});member.status=nextStatus;member.note=nextNote;saveAdminMember(member.email,{status:nextStatus,note:nextNote});row.dataset.status=member.status;const badge=row.querySelector('.member-status');badge.textContent=member.status;badge.className=`member-status ${member.status==='Activ'?'is-active':member.status==='În așteptare'?'is-pending':'is-rejected'}`;const avatar=row.querySelector('.member-avatar');avatar.querySelector('.member-note')?.remove();if(member.note)avatar.insertAdjacentHTML('beforeend',`<span class="member-note" title="${member.note.replace(/"/g,'&quot;')}">✎</span>`);dialog.close();}catch(error){dialog.querySelector('.admin-action').textContent='Eroare · încearcă din nou';}});dialog.addEventListener('close',()=>dialog.remove());}
function enhanceAdminContacts(){const table=app.querySelector('.members-table table');if(!table||table.querySelector('.contact-actions'))return;table.querySelector('thead tr')?.insertAdjacentHTML('beforeend','<th>Interese</th><th>Contact</th><th>Acțiuni</th>');table.querySelectorAll('tbody tr').forEach((row,index)=>{const member=ADMIN_MEMBERS[index];const phone=member.phone.replace(/\s/g,'');row.querySelector('td:nth-child(2)')?.insertAdjacentHTML('afterend',`<td><div class="interest-list">${member.interests.split(', ').map(interest=>`<span>${interest}</span>`).join('')}</div></td>`);row.insertAdjacentHTML('beforeend',`<td><div class="contact-actions"><a href="tel:${phone}" title="Sună">☎</a><a href="https://wa.me/${phone.replace('+','')}" target="_blank" rel="noopener" title="WhatsApp">◉</a><a href="mailto:${member.email}" title="Email">✉</a><a href="/mesaje" title="Mesaj pe platformă">✦</a></div><small>${member.phone}</small></td><td><button class="edit-member" type="button">Editează</button></td>`);row.querySelector('.edit-member').addEventListener('click',()=>openMemberEditor(member,row));});}
function compactAdminPills(){app.querySelectorAll('.member-roles,.interest-list').forEach(group=>{if(group.dataset.compacted)return;const pills=[...group.querySelectorAll('span')];const limit=group.classList.contains('member-roles')?2:4;group.title=pills.map(pill=>pill.textContent.trim()).join(', ');pills.slice(limit).forEach(pill=>pill.remove());if(pills.length>limit)group.insertAdjacentHTML('beforeend',`<span class="pill-overflow" title="${group.title}">+${pills.length-limit}</span>`);group.dataset.compacted='true';});}
function bind(){app.querySelector('[data-menu]')?.addEventListener('click',()=>{mobileOpen=!mobileOpen;render();});app.querySelectorAll('a[href]').forEach(a=>a.addEventListener('click',e=>{const raw=a.getAttribute('href');const u=raw?.startsWith(BASE_PATH)?raw.slice(BASE_PATH.length)||'/':raw;if(u?.startsWith('/')){e.preventDefault();go(u);}}));app.querySelectorAll('.feed-choice,.profile-choice').forEach(button=>button.addEventListener('click',()=>button.classList.toggle('selected')));const filterInputs=[...app.querySelectorAll('#member-search,#member-role,#member-city,#member-status,#member-interest')];const rows=[...app.querySelectorAll('[data-member-row]')];const matches=(row,values,skip='')=>{const [search,role,city,status,interest]=values;return (!search||`${row.dataset.name} ${row.dataset.email}`.includes(search))&&(!role||skip==='role'||row.dataset.roles.toLowerCase().includes(role))&&(!city||skip==='city'||row.dataset.city.toLowerCase()===city)&&(!status||skip==='status'||row.dataset.status.toLowerCase()===status)&&(!interest||skip==='interest'||row.dataset.interests.toLowerCase().includes(interest));};const applyFilters=()=>{const values=filterInputs.map(input=>input?.value.toLowerCase()||'');let visible=0;rows.forEach(row=>{const match=matches(row,values);row.hidden=!match;if(match)visible++;});const count=app.querySelector('#filter-count');if(count)count.textContent=`${visible} ${visible===1?'membru':'membri'}`;[['member-role','role'],['member-city','city'],['member-status','status'],['member-interest','interest']].forEach(([id,field])=>{const select=app.querySelector(`#${id}`);if(!select)return;[...select.options].slice(1).forEach(option=>{const optionRows=rows.filter(row=>{const value=field==='role'?row.dataset.roles.toLowerCase():field==='interest'?row.dataset.interests.toLowerCase():row.dataset[field].toLowerCase();return value.includes(option.value.toLowerCase())&&matches(row,values,field);});const label=option.textContent.replace(/ \(\d+\)$/,'');option.textContent=`${label} (${optionRows.length})`;});});};filterInputs.forEach(input=>input?.addEventListener('input',applyFilters));app.querySelector('#filter-reset')?.addEventListener('click',()=>{filterInputs.forEach(input=>{if(input)input.value='';});applyFilters();});app.querySelector('[data-signout]')?.addEventListener('click',async()=>{await signOut();currentUser=null;go('/');});app.querySelector('#auth-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{const r=await signInWithEmail(d.email,d.display_name);currentUser=r.user||await getCurrentUser();authNotice=r.mode==='otp'?'Ți-am trimis un link pe email.':'';go('/feed');}catch(err){authNotice=err.message||'Autentificarea nu a reușit.';render();}});}
function render(){document.body.classList.toggle('admin-mode',path()==='/admin');if(path()==='/admin')app.innerHTML=adminPageView();else if(path()==='/auth')app.innerHTML=publicViews.auth();else if(path()==='/exploreaza')app.innerHTML=publicViews.explore();else if(path()==='/profil')app.innerHTML=publicViews.profile();else if(path()==='/feed')app.innerHTML=publicViews.feed();else {const title=ROUTES[path()]||DIRECTIONS.find(([u])=>u===path())?.[1]||'Pagină';app.innerHTML=publicViews.shell(title,path().slice(1).replaceAll('/','-')||'home');}bind();if(path()==='/admin'){enhanceAdminContacts();const header=app.querySelector('.members-table thead tr');if(header&&header.children[6]?.textContent==='Interese')header.insertBefore(header.children[6],header.children[2]);app.querySelectorAll('.members-table tbody tr').forEach(row=>{const cityCell=row.children[3];if(cityCell&&!cityCell.dataset.fullCity){const full=cityCell.textContent.trim();cityCell.dataset.fullCity=full;cityCell.innerHTML=`<span class="city-short" title="${full}">${full.slice(0,6)}…</span>`;}});app.querySelectorAll('.contact-actions a[title="WhatsApp"]').forEach((whatsapp,index)=>{whatsapp.title=`WhatsApp: ${ADMIN_MEMBERS[index]?.phone||''}`;});app.querySelectorAll('.member-avatar').forEach((avatar,index)=>{if(ADMIN_MEMBERS[index]?.note)avatar.insertAdjacentHTML('beforeend',`<span class="member-note" title="${ADMIN_MEMBERS[index].note.replace(/"/g,'&quot;')}">✎</span>`);});compactAdminPills();syncAdminFilterControls();void hydrateAdminMembers();}if(path()==='/exploreaza')enhanceExploreFilters();}
window.addEventListener('popstate',render);void getCurrentUser().then(async u=>{currentUser=u;try{await hydrateStateFromSupabase(u);}catch(error){console.warn('Profile hydration unavailable',error);}render();void hydratePublicContent();});
app.addEventListener('change',event=>{if(path()!=='/admin'||!event.target.matches('#member-role,#member-city,#member-status,#member-interest'))return;const rows=[...app.querySelectorAll('[data-member-row]')];const filters={role:app.querySelector('#member-role')?.value.toLowerCase()||'',city:app.querySelector('#member-city')?.value.toLowerCase()||'',status:app.querySelector('#member-status')?.value.toLowerCase()||'',interest:app.querySelector('#member-interest')?.value.toLowerCase()||''};[['member-role','role','Toate rolurile'],['member-city','city','Toate orașele'],['member-status','status','Orice status'],['member-interest','interest','Orice interes']].forEach(([id,field,label])=>{const select=app.querySelector(`#${id}`);if(!select)return;const count=rows.filter(row=>Object.entries(filters).every(([key,value])=>key===field||!value||(key==='role'?row.dataset.roles.toLowerCase().includes(value):key==='interest'?row.dataset.interests.toLowerCase().includes(value):row.dataset[key].toLowerCase()===value))).length;select.options[0].textContent=`${label} (${count})`;});});
app.addEventListener('click',event=>{const note=event.target.closest?.('.member-note');app.querySelectorAll('.member-note.is-open').forEach(item=>{if(item!==note)item.classList.remove('is-open');});if(note){if(note.title&&!note.dataset.note){note.dataset.note=note.title;note.removeAttribute('title');}note.classList.toggle('is-open');}});
app.addEventListener('mouseover',event=>{const note=event.target.closest?.('.member-note');if(note&&note.title&&!note.dataset.note){note.dataset.note=note.title;note.removeAttribute('title');}});
app.addEventListener('mouseover',event=>{const status=event.target.closest?.('.member-status');if(status)status.title=status.textContent;});
app.addEventListener('change',event=>{if(path()==='/admin'&&event.target.matches('#member-role,#member-city,#member-status,#member-interest'))event.target.dispatchEvent(new Event('input',{bubbles:true}));});
app.addEventListener('change',event=>{if(path()!=='/exploreaza'||!event.target.matches('.explore-filter'))return;void refreshExploreFromServer();const filters={};app.querySelectorAll('.explore-filter').forEach(select=>filters[select.dataset.filter]=select.value);let visible=0;app.querySelectorAll('[data-result]').forEach(card=>{const show=Object.entries(filters).every(([key,value])=>!value||card.dataset[key]===value);card.hidden=!show;if(show)visible++;});const count=app.querySelector('[data-explore-count]');if(count)count.textContent=`${visible} rezultate`;const empty=app.querySelector('.empty-explore');if(empty)empty.hidden=visible>0;});app.addEventListener('click',event=>{if(path()!=='/exploreaza'||!event.target.closest('[data-explore-reset]'))return;app.querySelectorAll('.explore-filter').forEach(select=>select.value='');app.querySelectorAll('[data-result]').forEach(card=>card.hidden=false);const count=app.querySelector('[data-explore-count]');if(count)count.textContent=`${app.querySelectorAll('[data-result]').length} rezultate`;const empty=app.querySelector('.empty-explore');if(empty)empty.hidden=true;void refreshExploreFromServer();});
app.addEventListener('input',event=>{if(path()!=='/exploreaza'||!event.target.matches('.explore-search'))return;void refreshExploreFromServer();const query=event.target.value.toLowerCase();const location=app.querySelector('[data-filter="location"]')?.value||'';let visible=0;app.querySelectorAll('[data-result]').forEach(card=>{const show=(!query||card.textContent.toLowerCase().includes(query))&&(!location||card.dataset.location===location);card.hidden=!show;if(show)visible++;});updateExploreLocationCounts(query);const count=app.querySelector('[data-explore-count]');if(count)count.textContent=`${visible} rezultate`;const empty=app.querySelector('.empty-explore');if(empty)empty.hidden=visible>0;});
app.addEventListener('click',event=>{if(path()!=='/exploreaza'||!event.target.closest('[data-explore-reset]'))return;app.querySelector('.explore-search')?.setAttribute('value','');if(app.querySelector('.explore-search'))app.querySelector('.explore-search').value='';updateExploreLocationCounts();});
app.addEventListener('click',event=>{const button=event.target.closest?.('[data-explore-detail]');if(path()!=='/exploreaza'||!button)return;openExploreDetail(button.dataset.exploreDetail,Number(button.dataset.detailIndex));});
app.addEventListener('click',event=>{const button=event.target.closest?.('[data-profile-type]');if(path()!=='/profil'||!button)return;const type=button.dataset.profileType;const value=button.dataset.profileValue;const next={...demoProfile,roles:[...demoProfile.roles],interests:[...demoProfile.interests]};next[type]=next[type].includes(value)?next[type].filter(item=>item!==value):[...next[type],value];demoProfile.roles=next.roles;demoProfile.interests=next.interests;if(demoMember){demoMember.roles=next.roles;demoMember.interests=next.interests.join(', ');}saveProfileDemo(next);void saveProfileToSupabase(next,currentUser).catch(error=>console.warn('Profile sync failed',error));button.classList.toggle('selected',next[type].includes(value));});
app.addEventListener('change',event=>{if(path()!=='/profil'||!event.target.matches('[data-profile-city]'))return;demoProfile.city=event.target.value;if(demoMember)demoMember.city=demoProfile.city;demoFeed.city=demoProfile.city;saveProfileDemo(demoProfile);saveFeedDemo();void Promise.all([saveProfileToSupabase(demoProfile,currentUser),saveFeedToSupabase(demoFeed,currentUser)]).catch(error=>console.warn('Preference sync failed',error));});
app.addEventListener('click',event=>{const button=event.target.closest?.('[data-feed-interest]');if(path()!=='/feed'||!button)return;const value=button.dataset.feedInterest;demoFeed.interests=demoFeed.interests.includes(value)?demoFeed.interests.filter(item=>item!==value):[...demoFeed.interests,value];saveFeedDemo();void saveFeedToSupabase(demoFeed,currentUser).catch(error=>console.warn('Feed sync failed',error));render();});
app.addEventListener('change',event=>{if(path()!=='/feed'||!event.target.matches('[data-feed-radius]'))return;demoFeed.radius=Number(event.target.value);saveFeedDemo();void saveFeedToSupabase(demoFeed,currentUser).catch(error=>console.warn('Feed sync failed',error));render();});
app.addEventListener('click',event=>{if(path()!=='/admin'||!event.target.closest('#filter-reset'))return;['#member-role','#member-city','#member-status','#member-interest'].forEach(selector=>{const select=app.querySelector(selector);if(select)select.selectedIndex=0;});const search=app.querySelector('#member-search');if(search)search.value='';app.querySelector('#member-role')?.dispatchEvent(new Event('input',{bubbles:true}));});
app.addEventListener('click',event=>{const button=event.target.closest?.('[data-admin-page]');if(path()!=='/admin'||!button||button.disabled)return;void loadAdminPage(Number(button.dataset.adminPage));});
app.addEventListener('input',event=>{if(path()!=='/admin'||!event.target.matches('#member-search,#member-role,#member-city,#member-status,#member-interest'))return;adminFilters.search=app.querySelector('#member-search')?.value.trim()||'';adminFilters.role=app.querySelector('#member-role')?.value||'';adminFilters.city=app.querySelector('#member-city')?.value||'';adminFilters.status=app.querySelector('#member-status')?.value||'';adminFilters.interest=app.querySelector('#member-interest')?.value||'';if(adminHasServerPage){clearTimeout(adminFilterTimer);adminFilterTimer=setTimeout(()=>void loadAdminFilteredMembers(),220);}});
app.addEventListener('click',event=>{if(path()!=='/admin'||!event.target.closest('#filter-reset'))return;Object.keys(adminFilters).forEach(key=>{adminFilters[key]='';});if(adminHasServerPage){clearTimeout(adminFilterTimer);void loadAdminFilteredMembers();}});
new MutationObserver(()=>document.querySelectorAll('#member-status option, .member-editor select option').forEach(option=>{if(option.textContent.startsWith('Arhivat'))option.textContent=option.textContent.replace('Arhivat','Dezaprobat');})).observe(document.body,{childList:true,subtree:true});
new MutationObserver(()=>{enhanceFeedView();enhanceFeedInterestCounts();if(!app.querySelector('.saved-feed-section'))enhanceFeedSaved();ensureSavedFeedPanel();syncFeedIndexes();if(!app.querySelector('.feed-comments'))enhanceFeedComments();enhanceFeedCityFilter();enhanceFeedCityOptions();enhanceFeedCityResults();syncCreateContactField();}).observe(app,{childList:true});
