new MutationObserver(()=>{if(path()==='/admin'){enhanceAdminOnboarding();enhanceAdminPosts();void hydrateAdminPosts();}}).observe(app,{childList:true});
app.addEventListener('click',event=>{const button=event.target.closest?.('[data-feed-mode]');if(path()!=='/feed'||!button)return;feedMode=button.dataset.feedMode;feedNotice='';render();});
app.addEventListener('click',async event=>{const button=event.target.closest?.('[data-demo-login]');if(path()!=='/auth'||!button)return;const r=await signInWithEmail('radu.calin@demo.viziunea.ro','Radu Călin');currentUser=r.user;go('/exploreaza#oameni');});
app.addEventListener('submit',async event=>{if(path()!=='/feed'||!event.target.matches('#create-post-form'))return;event.preventDefault();const formData=new FormData(event.target);const data=Object.fromEntries(formData);data.interests=formData.getAll('interests');if(!data.interests.length){feedNotice='Selectează cel puțin un interes.';enhanceFeedView();syncCreateContactField();return;}try{await createPost(data,currentUser);feedNotice='Postarea a fost trimisă spre moderare.';event.target.reset();}catch(error){feedNotice=error.message||'Postarea nu a putut fi trimisă.';}enhanceFeedView();syncCreateContactField();});
