app.addEventListener('click',event=>{if(path()!=='/mesaje')return;const button=event.target.closest?.('[data-message-member]');if(!button)return;messageTargetEmail=button.dataset.messageMember;renderMessages();app.querySelector('.chat-composer textarea')?.focus();});
app.addEventListener('input',event=>{if(path()!=='/mesaje'||!event.target.matches('[data-message-search]'))return;const query=event.target.value.trim().toLowerCase();let visible=0;app.querySelectorAll('[data-message-members] [data-message-member]').forEach(card=>{const show=!query||card.dataset.name.includes(query);card.hidden=!show;if(show)visible++;});const count=app.querySelector('[data-message-result-count]');if(count)count.textContent=visible;const empty=app.querySelector('[data-message-empty]');if(empty)empty.hidden=visible>0;});
app.addEventListener('change',event=>{if(path()!=='/mesaje'||!event.target.matches('[data-message-filter]'))return;const filters={};app.querySelectorAll('[data-message-filter]').forEach(select=>filters[select.dataset.messageFilter]=select.value);let visible=0;app.querySelectorAll('[data-message-members] [data-message-member]').forEach(card=>{const show=(!filters.city||card.dataset.city===filters.city)&&(!filters.distance||Number(card.dataset.distance)<=Number(filters.distance))&&(!filters.role||card.dataset.roles.split('|').includes(filters.role))&&(!filters.interest||card.dataset.interests.split(', ').includes(filters.interest));card.hidden=!show;if(show)visible++;});const count=app.querySelector('[data-message-result-count]');if(count)count.textContent=visible;const empty=app.querySelector('[data-message-empty]');if(empty)empty.hidden=visible>0;});
app.addEventListener('submit',async event=>{if(path()!=='/mesaje'||!event.target.matches('#messenger-chat-form'))return;event.preventDefault();const recipient=ADMIN_MEMBERS.find(member=>member.email===messageTargetEmail);const body=new FormData(event.target).get('body');if(!recipient)return;try{await sendMessage({from:currentUser,to:{id:`demo:${recipient.email}`,email:recipient.email,user_metadata:{full_name:recipient.name}},body});messagingData=(await listMessages(currentUser)).data;renderMessages();}catch(error){event.target.insertAdjacentHTML('afterend',`<p class="chat-error">${esc(error.message||'Mesajul nu a putut fi trimis.')}</p>`);}});
function applyMessageDirectoryFilters(){if(path()!=='/mesaje')return;const values={};app.querySelectorAll('[data-message-filter]').forEach(select=>values[select.dataset.messageFilter]=select.value);const query=app.querySelector('[data-message-search]')?.value.trim().toLowerCase()||'';let visible=0;app.querySelectorAll('[data-message-members] [data-message-member]').forEach(card=>{const show=(!query||card.dataset.name.includes(query))&&(!values.city||messageDistance(card.dataset.city,values.city)<=Number(values.distance||9999))&&(!values.distance||messageDistance(card.dataset.city,values.city||demoProfile.city)<=Number(values.distance))&&(!values.role||card.dataset.roles.split('|').includes(values.role))&&(!values.interest||card.dataset.interests.split(', ').includes(values.interest));card.hidden=!show;if(show)visible++;});const count=app.querySelector('[data-message-result-count]');if(count)count.textContent=visible;const empty=app.querySelector('[data-message-empty]');if(empty)empty.hidden=visible>0;}
app.addEventListener('input',event=>{if(path()==='/mesaje'&&(event.target.matches('[data-message-search]')))applyMessageDirectoryFilters();});
app.addEventListener('change',event=>{if(path()==='/mesaje'&&event.target.matches('[data-message-filter]'))applyMessageDirectoryFilters();});
app.addEventListener('click',async event=>{if(path()!=='/admin')return;const button=event.target.closest?.('[data-moderation-action]');if(!button)return;button.disabled=true;try{await updatePostStatus(button.dataset.postId,button.dataset.moderationAction);adminPosts=(await listModerationPosts()).data;const section=app.querySelector('.admin-feed-moderation');section?.remove();enhanceAdminPosts();}catch(error){button.disabled=false;console.warn('Feed moderation update failed',error);}});
const FEED_SAVED_KEY='viziunea.feed.saved.v1';
function getSavedFeedIndexes(){try{return JSON.parse(localStorage.getItem(FEED_SAVED_KEY)||'[]');}catch{return [];}}
function setSavedFeedIndexes(indexes){localStorage.setItem(FEED_SAVED_KEY,JSON.stringify([...new Set(indexes)]));}
function enhanceFeedSaved(){if(path()!=='/feed'||feedMode==='create')return;const page=app.querySelector('.feed-page');const posts=page?.querySelectorAll('.feed-post');if(!page||!posts?.length)return;posts.forEach((post,index)=>{post.dataset.feedIndex=index;const save=post.querySelector('[aria-label="Salvează"]');const share=post.querySelector('[aria-label="Distribuie"]');if(save){save.dataset.feedAction='save';save.textContent=getSavedFeedIndexes().includes(index)?'♥':'♡';save.classList.toggle('is-saved',getSavedFeedIndexes().includes(index));}if(share)share.dataset.feedAction='share';});let saved=page.querySelector('.saved-feed-section');if(!saved){saved=document.createElement('section');saved.className='saved-feed-section';page.querySelector('.community-feed')?.after(saved);}const indexes=getSavedFeedIndexes().filter(index=>FEED_POSTS[index]);saved.innerHTML=`<header><div><span class="page-kicker">La îndemână</span><h2>Postări salvate</h2></div><strong>${indexes.length} ${indexes.length===1?'postare':'postări'}</strong></header>${indexes.length?`<div class="saved-feed-list">${indexes.map(index=>{const post=FEED_POSTS[index];return `<article class="saved-feed-item"><div><strong>${esc(post.title)}</strong><small>${esc(post.author)} · ${esc(post.city)}</small></div><button type="button" data-remove-saved="${index}" aria-label="Elimină din salvate">×</button></article>`;}).join('')}</div>`:'<p class="saved-feed-empty">Postările cărora le dai inimă apar aici ca să le găsești rapid mai târziu.</p>'}`;}
function openFeedShare(post){const dialog=document.createElement('dialog');dialog.className='feed-share-dialog';const members=ADMIN_MEMBERS.filter(member=>member.email!==currentUser?.email);const linkUrl=`${location.origin}${BASE_PATH}/feed`;const preset=`Îți trimit această postare din Viziunea: „${post.title}”\n\n${post.body}\n\nVezi postarea în Feed: ${linkUrl}`;dialog.innerHTML=`<form method="dialog"><button class="detail-close" value="cancel" aria-label="Închide">×</button><span class="page-kicker">Distribuie postarea</span><h2>${esc(post.title)}</h2><p class="feed-share-preview">${esc(post.body)}</p><label>Mesajul tău<textarea name="share_body" rows="6">${esc(preset)}</textarea></label><div class="feed-share-options"><button type="button" data-share-copy>Copiază linkul</button><a href="https://wa.me/?text=${encodeURIComponent(preset)}" target="_blank" rel="noopener">WhatsApp</a><a href="mailto:?subject=${encodeURIComponent(`Postare Viziunea: ${post.title}`)}&body=${encodeURIComponent(preset)}">Email</a></div><div class="feed-share-member"><label>Trimite unui membru Viziunea<select name="recipient"><option value="">Alege un membru...</option>${members.map(member=>`<option value="${esc(member.email)}">${esc(member.name)} · ${esc(member.city)}</option>`).join('')}</select></label><button type="button" class="admin-action" data-share-member>Trimite mesajul <span>→</span></button></div><p class="feed-share-notice"></p></form>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('[data-share-copy]')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(linkUrl);dialog.querySelector('.feed-share-notice').textContent='Link copiat.';}catch{dialog.querySelector('.feed-share-notice').textContent=linkUrl;}});dialog.querySelector('[data-share-member]')?.addEventListener('click',async()=>{const email=dialog.querySelector('[name="recipient"]').value;const member=members.find(item=>item.email===email);if(!member){dialog.querySelector('.feed-share-notice').textContent='Alege un membru.';return;}try{await sendMessage({from:currentUser,to:{id:`demo:${member.email}`,email:member.email,user_metadata:{full_name:member.name}},body:dialog.querySelector('[name="share_body"]').value});dialog.querySelector('.feed-share-notice').textContent=`Postarea a fost trimisă lui ${member.name}.`;dialog.querySelector('[name="recipient"]').value='';}catch(error){dialog.querySelector('.feed-share-notice').textContent=error.message||'Mesajul nu a putut fi trimis.';}});dialog.addEventListener('close',()=>dialog.remove());}
app.addEventListener('click',event=>{if(path()!=='/feed')return;const remove=event.target.closest?.('[data-remove-saved]');if(remove){setSavedFeedIndexes(getSavedFeedIndexes().filter(index=>index!==Number(remove.dataset.removeSaved)));enhanceFeedSaved();return;}const action=event.target.closest?.('[data-feed-action]');if(!action)return;const card=action.closest('.feed-post');const index=Number(card?.dataset.feedIndex);const post=FEED_POSTS[index];if(!post)return;if(action.dataset.feedAction==='save'){const saved=getSavedFeedIndexes();setSavedFeedIndexes(saved.includes(index)?saved.filter(item=>item!==index):[...saved,index]);enhanceFeedSaved();}else if(action.dataset.feedAction==='share')openFeedShare(post);});
function syncFeedIndexes(){if(path()!=='/feed')return;app.querySelectorAll('.feed-post').forEach(post=>{const title=post.querySelector('h3')?.textContent.trim();const index=FEED_POSTS.findIndex(item=>item.title===title);if(index>=0)post.dataset.feedIndex=index;});}
function ensureSavedFeedPanel(){if(path()!=='/feed'||feedMode==='create')return;const page=app.querySelector('.feed-page');if(!page||page.querySelector('.saved-feed-section'))return;const section=document.createElement('section');section.className='saved-feed-section';section.innerHTML='<header><div><span class="page-kicker">La îndemână</span><h2>Postări salvate</h2></div><strong>0 postări</strong></header><p class="saved-feed-empty">Postările cărora le dai inimă apar aici ca să le găsești rapid mai târziu.</p>';page.querySelector('.community-feed')?.after(section);}
function commentMentionMembers(body){const tokens=body.match(/@[\p{L}0-9._-]+/gu)||[];return ADMIN_MEMBERS.filter(member=>tokens.some(token=>{const handle=token.slice(1).toLocaleLowerCase('ro');return member.name.toLocaleLowerCase('ro').split(/\s+/)[0]===handle||member.email.split('@')[0].toLocaleLowerCase()===handle;}));}
function renderCommentTree(comments,parentId=null,depth=0){return comments.filter(comment=>comment.parentId===parentId).map(comment=>`<article class="feed-comment ${depth?'is-reply':''}" data-comment-id="${esc(comment.id)}"><span class="feed-comment-avatar">${esc(comment.authorName[0]||'M')}</span><div class="feed-comment-body"><div><strong>${esc(comment.authorName)}</strong><time>${new Date(comment.created_at).toLocaleString('ro-RO')}</time></div><p>${esc(comment.body).replace(/(@[\p{L}0-9._-]+)/gu,'<b>$1</b>')}</p><button type="button" data-comment-reply="${esc(comment.id)}">Răspunde</button>${renderCommentTree(comments,comment.id,depth+1)}</div></article>`).join('');}
function enhanceFeedComments(){if(path()!=='/feed'||feedMode==='create')return;app.querySelectorAll('.feed-post').forEach(post=>{const index=Number(post.dataset.feedIndex);if(!Number.isInteger(index)||index<0)return;let section=post.querySelector('.feed-comments');if(!section){section=document.createElement('section');section.className='feed-comments';post.append(section);}const comments=listComments(`demo-feed-${index}`);section.innerHTML=`<div class="feed-comments-heading"><strong>${comments.length} ${comments.length===1?'comentariu':'comentarii'}</strong></div>${comments.length?`<div class="feed-comment-list">${renderCommentTree(comments)}</div>`:''}<form class="feed-comment-form" data-comment-form data-post-index="${index}"><textarea name="body" rows="1" required placeholder="Scrie un comentariu..."></textarea><button type="submit">Comentează</button></form>`;});}
app.addEventListener('click',event=>{if(path()!=='/feed')return;const reply=event.target.closest?.('[data-comment-reply]');if(!reply)return;const comment=reply.closest('.feed-post')?.querySelector('[data-comment-form]');if(!comment)return;comment.dataset.parentId=reply.dataset.commentReply;const textarea=comment.querySelector('textarea');textarea.placeholder='Răspunde la acest comentariu...';textarea.focus();});
app.addEventListener('submit',async event=>{if(path()!=='/feed'||!event.target.matches('[data-comment-form]'))return;event.preventDefault();const form=event.target;const body=String(new FormData(form).get('body')||'').trim();const index=Number(form.dataset.postIndex);const post=FEED_POSTS[index];if(!post)return;try{const mentions=commentMentionMembers(body);addComment({postKey:`demo-feed-${index}`,author:currentUser,body,parentId:form.dataset.parentId||null,mentions:mentions.map(member=>member.email)});await Promise.all(mentions.map(member=>notifyMention({from:currentUser,to:{id:`demo:${member.email}`,email:member.email,user_metadata:{full_name:member.name}},body,postTitle:post.title})));app.querySelectorAll('.feed-comments').forEach(section=>section.remove());enhanceFeedComments();}catch(error){form.insertAdjacentHTML('afterend',`<p class="feed-comment-error">${esc(error.message||'Comentariul nu a putut fi trimis.')}</p>`);}});
function feedPostInterests(post){return Array.isArray(post.interests)&&post.interests.length?post.interests:[post.interest].filter(Boolean);}
function enhanceFeedInterestCounts(){if(path()!=='/feed'||feedMode==='create')return;const counts=FEED_POSTS.reduce((result,post)=>{feedPostInterests(post).forEach(interest=>{result[interest]=(result[interest]||0)+1;});return result;},{});app.querySelectorAll('.feed-choice').forEach(button=>{const label=button.dataset.feedInterest;const text=`${label} (${counts[label]||0})`;if(button.textContent!==text)button.textContent=text;});}
function enhanceFeedCityOptions(){if(path()!=='/feed'||feedMode==='create')return;const select=app.querySelector('[data-feed-city]');if(!select)return;const filtered=FEED_POSTS.filter(post=>!demoFeed.interests.length||demoFeed.interests.some(interest=>feedPostInterests(post).includes(interest)));const counts=filtered.reduce((result,post)=>{if(post.city)result[post.city]=(result[post.city]||0)+1;return result;},{});const html=`<option value="">Toate orașele (${filtered.length})</option>${Object.entries(counts).filter(([,count])=>count>0).sort(([a],[b])=>a.localeCompare(b,'ro')).map(([city,count])=>`<option value="${esc(city)}">${esc(city)} (${count})</option>`).join('')}`;if(select.innerHTML!==html){const current=select.value;select.innerHTML=html;select.value=Object.prototype.hasOwnProperty.call(counts,current)?current:'';}}
function enhanceFeedCityResults(){if(path()!=='/feed'||feedMode==='create')return;const active=FEED_POSTS.filter(post=>(!demoFeed.interests.length||demoFeed.interests.some(interest=>feedPostInterests(post).includes(interest)))&&(post.distance===0||post.distance<=Number(demoFeed.radius)));const visible=active.filter(post=>!demoFeed.city||post.city===demoFeed.city);app.querySelectorAll('.feed-post').forEach(post=>{const index=Number(post.dataset.feedIndex);post.hidden=!visible.some(item=>FEED_POSTS.indexOf(item)===index);});const heading=app.querySelector('.community-feed h2');if(heading)heading.textContent=`${visible.length} ${visible.length===1?'postare relevantă':'postări relevante'}`;}
function syncMessageDistanceFilter(){if(path()!=='/mesaje')return;const city=app.querySelector('[data-message-filter="city"]');const distance=app.querySelector('[data-message-filter="distance"]');if(!city||!distance)return;const hasCity=Boolean(city.value);distance.disabled=!hasCity;if(!hasCity){distance.value='';return;}if(!distance.value)distance.value='100';}
app.addEventListener('change',event=>{if(path()!=='/mesaje'||!event.target.matches('[data-message-filter]'))return;syncMessageDistanceFilter();applyMessageDirectoryFilters();});
function enhanceMessageInterestFilter(){if(path()!=='/mesaje')return;const select=app.querySelector('[data-message-filter="interest"]');if(!select)return;const options=[...select.options].slice(1);const fieldset=document.createElement('fieldset');fieldset.className='message-interest-filter';fieldset.innerHTML=`<legend>Interese</legend><div>${options.map(option=>`<label><input type="checkbox" data-message-filter="interest" data-message-interest value="${esc(option.value)}"><span>${esc(option.textContent)}</span></label>`).join('')}</div>`;select.replaceWith(fieldset);refreshMessageDirectory();}
function refreshMessageDirectory(){if(path()!=='/mesaje')return;const values={city:app.querySelector('[data-message-filter="city"]')?.value||'',distance:app.querySelector('[data-message-filter="distance"]')?.value||'',role:app.querySelector('[data-message-filter="role"]')?.value||''};const interests=[...app.querySelectorAll('[data-message-interest]:checked')].map(input=>input.value);const query=app.querySelector('[data-message-search]')?.value.trim().toLowerCase()||'';const cards=[...app.querySelectorAll('[data-message-members] [data-message-member]')];let visible=0;cards.forEach(card=>{const matches=card.dataset.interests.split(', ').filter(Boolean);const score=interests.filter(interest=>matches.includes(interest)).length;const show=(!query||card.dataset.name.includes(query))&&(!values.city||messageDistance(card.dataset.city,values.city)<=Number(values.distance||9999))&&(!values.distance||messageDistance(card.dataset.city,values.city||demoProfile.city)<=Number(values.distance))&&(!values.role||card.dataset.roles.split('|').includes(values.role))&&(!interests.length||score>0);card.hidden=!show;card.dataset.interestScore=score;card.style.order=show?String(100-score):'999';if(show)visible++;});const count=app.querySelector('[data-message-result-count]');if(count)count.textContent=visible;const empty=app.querySelector('[data-message-empty]');if(empty)empty.hidden=visible>0;const container=app.querySelector('[data-message-members]');if(container)cards.sort((a,b)=>Number(a.dataset.interestScore||0)<Number(b.dataset.interestScore||0)?1:-1).forEach(card=>container.append(card));}
app.addEventListener('input',event=>{if(path()==='/mesaje'&&event.target.matches('[data-message-search]'))refreshMessageDirectory();});
app.addEventListener('change',event=>{if(path()==='/mesaje'&&(event.target.matches('[data-message-filter]')||event.target.matches('[data-message-interest]'))){syncMessageDistanceFilter();refreshMessageDirectory();}});
